//! Scoring harness (Phase 0.6): run a checker over every fixture and
//! measure it.
//!
//! Fixtures:
//! - **synthetic clean**: generated by `synth`; expected findings: none
//! - **real labelled**: `fixtures/recorded/<id>/run<n>/` with a filled-in
//!   `labels.json`; expected findings come from its `defects`, findings
//!   in `tolerated` (accurate but harmless, "grey") count either way, and
//!   `hallucinated` marks sessions where the agent claimed something false
//!   (whether or not a static check can see it)
//! - **mutations**: one injected defect each, generated from every clean
//!   fixture (synthetic, and real labelled runs with no defects)
//!
//! Measured: precision and recall per check, false alarms on clean
//! fixtures, determinism (each fixture checked twice, compared byte for
//! byte) and checker time.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::Instant;

use anyhow::{Context, Result};
use checks::{Finding, Recording, Report};
use serde_json::{Value, json};

use crate::mutate::{self, Expected};
use crate::synth;

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Kind {
    SyntheticClean,
    RealLabelled,
    Mutation,
}

impl Kind {
    pub fn as_str(self) -> &'static str {
        match self {
            Kind::SyntheticClean => "synthetic-clean",
            Kind::RealLabelled => "real-labelled",
            Kind::Mutation => "mutation",
        }
    }
}

#[derive(Debug, Clone)]
pub struct Fixture {
    pub name: String,
    pub kind: Kind,
    pub dir: PathBuf,
    pub expected: Vec<Expected>,
    /// Findings that are neither required nor false alarms.
    pub tolerated: Vec<Expected>,
    /// Real sessions only: did the agent claim something false?
    pub hallucinated: Option<bool>,
}

#[derive(Debug, Default, Clone)]
pub struct Collected {
    pub fixtures: Vec<Fixture>,
    /// (recording, reason) for real recordings left out.
    pub skipped: Vec<(String, String)>,
    /// (source, mutation) pairs where the mutation didn't apply.
    pub not_applicable: Vec<(String, String)>,
}

/// Expected findings from a labels.json, or `None` if it isn't labelled yet.
pub fn expected_from_labels(labels: &Value) -> Option<Vec<Expected>> {
    let labeller = labels.get("labeller").and_then(Value::as_str).unwrap_or("");
    if labeller.trim().is_empty() {
        return None;
    }
    let defects = labels.get("defects").and_then(Value::as_array).cloned().unwrap_or_default();
    Some(
        defects
            .iter()
            .filter_map(|d| {
                let kind = d.get("type")?.as_str()?;
                // Defect types use mutation names; unknown types are kept
                // under their own name so they show up as missed.
                let check = mutate::check_for(kind).unwrap_or(kind);
                let file = d.get("file").and_then(Value::as_str).filter(|f| !f.is_empty());
                Some(Expected::new(check, file))
            })
            .collect(),
    )
}

/// Tolerated findings from a labels.json (`tolerated: [{type, file}]`).
pub fn tolerated_from_labels(labels: &Value) -> Vec<Expected> {
    labels
        .get("tolerated")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|d| {
            let kind = d.get("type")?.as_str()?;
            let file = d.get("file").and_then(Value::as_str).filter(|f| !f.is_empty());
            Some(Expected::new(mutate::check_for(kind).unwrap_or(kind), file))
        })
        .collect()
}

/// Build every fixture. Generated ones (synthetic and mutations) go under
/// `work`. Labels are read from each recording's own `labels.json`.
pub fn collect(recorded: &Path, work: &Path) -> Result<Collected> {
    collect_with_labels(recorded, None, work)
}

/// Where a recording's labels live: `<labels>/<prompt>/<run>.json` when a
/// labels folder is given and has one (labels are kept in git, recordings
/// aren't), else the recording's own `labels.json`.
pub fn labels_path(recorded: &Path, labels: Option<&Path>, dir: &Path) -> PathBuf {
    if let Some(root) = labels
        && let Ok(rel) = dir.strip_prefix(recorded)
    {
        let mut parts = rel.components().map(|c| c.as_os_str().to_string_lossy().into_owned());
        if let (Some(prompt), Some(run)) = (parts.next(), parts.next()) {
            let p = root.join(prompt).join(format!("{run}.json"));
            if p.is_file() {
                return p;
            }
        }
    }
    dir.join("labels.json")
}

/// Only the real labelled recordings (no synthetic sessions or mutations).
pub fn collect_real(recorded: &Path, labels: Option<&Path>) -> Result<Collected> {
    let mut c = Collected::default();
    add_real(&mut c, recorded, labels, &mut Vec::new())?;
    Ok(c)
}

fn add_real(c: &mut Collected, recorded: &Path, labels_root: Option<&Path>, clean_sources: &mut Vec<(String, PathBuf)>) -> Result<()> {
    for dir in real_recordings(recorded)? {
        let name = display_name(recorded, &dir);
        let labels = fs::read_to_string(labels_path(recorded, labels_root, &dir))
            .ok()
            .and_then(|t| serde_json::from_str::<Value>(&t).ok());
        match labels.as_ref().and_then(expected_from_labels) {
            None => c.skipped.push((name, "not labelled yet".into())),
            Some(expected) => {
                let labels = labels.as_ref().expect("labelled");
                // Real sessions seed mutations only when asked: 100+ of them
                // would multiply the run time (recall study, 2026-10-26).
                if expected.is_empty() && labels.get("mutation_source") == Some(&Value::Bool(true)) {
                    clean_sources.push((name.clone(), dir.clone()));
                }
                // Execution findings need a local execution record (`tattle verify
                // --write`); without one they can't be expected.
                let expected: Vec<Expected> = if dir.join("exec/record.json").is_file() {
                    expected
                } else {
                    expected.into_iter().filter(|e| !e.check.starts_with("exec.")).collect()
                };
                let tolerated = tolerated_from_labels(labels);
                let hallucinated = labels.get("hallucinated").and_then(Value::as_bool);
                c.fixtures.push(Fixture { name, kind: Kind::RealLabelled, dir, expected, tolerated, hallucinated });
            }
        }
    }
    Ok(())
}

/// [`collect`] with labels from a separate folder (see [`labels_path`]).
pub fn collect_with_labels(recorded: &Path, labels_root: Option<&Path>, work: &Path) -> Result<Collected> {
    let mut c = Collected::default();
    let mut clean_sources: Vec<(String, PathBuf)> = Vec::new();

    for s in synth::scenarios() {
        let dir = work.join("synthetic").join(s.name);
        synth::generate(&s, &dir)?;
        let name = format!("synthetic/{}", s.name);
        clean_sources.push((name.clone(), dir.clone()));
        c.fixtures.push(Fixture { name, kind: Kind::SyntheticClean, dir, expected: Vec::new(), tolerated: Vec::new(), hallucinated: None });
    }

    add_real(&mut c, recorded, labels_root, &mut clean_sources)?;

    for (source_name, source_dir) in &clean_sources {
        let out_root = work.join("mutations").join(source_name.replace('/', "__"));
        for (mutation, applied) in mutate::apply_all(source_dir, &out_root)? {
            match applied {
                Some(a) => c.fixtures.push(Fixture {
                    name: format!("{source_name}+{mutation}"),
                    kind: Kind::Mutation,
                    dir: out_root.join(mutation),
                    expected: a.expected,
                    tolerated: Vec::new(),
                    hallucinated: None,
                }),
                None => c.not_applicable.push((source_name.clone(), mutation.to_string())),
            }
        }
    }
    Ok(c)
}

/// `fixtures/recorded/<id>/run<n>/` folders containing an events.jsonl.
fn real_recordings(root: &Path) -> Result<Vec<PathBuf>> {
    let mut out = Vec::new();
    let Ok(prompts) = fs::read_dir(root) else {
        return Ok(out);
    };
    for prompt in prompts.flatten() {
        if let Ok(runs) = fs::read_dir(prompt.path()) {
            for run in runs.flatten() {
                if run.path().join("events.jsonl").is_file() {
                    out.push(run.path());
                }
            }
        }
    }
    out.sort();
    Ok(out)
}

fn display_name(root: &Path, dir: &Path) -> String {
    dir.strip_prefix(root).unwrap_or(dir).to_string_lossy().replace('\\', "/")
}

#[derive(Debug, Clone)]
pub struct FixtureResult {
    pub name: String,
    pub kind: Kind,
    pub expected: Vec<Expected>,
    pub found: Vec<Finding>,
    pub matched: Vec<Expected>,
    pub missed: Vec<Expected>,
    pub false_positives: Vec<Finding>,
    pub deterministic: bool,
    pub millis: f64,
    pub error: Option<String>,
    pub hallucinated: Option<bool>,
}

/// Match findings to expectations. A finding matches when the check id is
/// the same and, if the expectation names a file, the file is the same.
pub fn match_findings(expected: &[Expected], found: &[Finding]) -> (Vec<Expected>, Vec<Expected>, Vec<Finding>) {
    let mut used = vec![false; found.len()];
    let mut matched = Vec::new();
    let mut missed = Vec::new();
    for e in expected {
        let hit = found.iter().enumerate().position(|(i, f)| {
            !used[i] && f.check == e.check && (e.file.is_none() || f.file == e.file)
        });
        match hit {
            Some(i) => {
                used[i] = true;
                matched.push(e.clone());
            }
            None => missed.push(e.clone()),
        }
    }
    let false_positives = found.iter().zip(&used).filter(|(_, u)| !**u).map(|(f, _)| f.clone()).collect();
    (matched, missed, false_positives)
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct CheckStats {
    pub tp: usize,
    pub fp: usize,
    pub fn_: usize,
}

impl CheckStats {
    pub fn precision(&self) -> Option<f64> {
        let d = self.tp + self.fp;
        (d > 0).then(|| self.tp as f64 / d as f64)
    }

    pub fn recall(&self) -> Option<f64> {
        let d = self.tp + self.fn_;
        (d > 0).then(|| self.tp as f64 / d as f64)
    }
}

#[derive(Debug, Clone)]
pub struct ScoreReport {
    pub results: Vec<FixtureResult>,
    pub skipped: Vec<(String, String)>,
    pub not_applicable: Vec<(String, String)>,
}

impl ScoreReport {
    pub fn checks(&self) -> BTreeMap<String, CheckStats> {
        let mut stats: BTreeMap<String, CheckStats> = checks::catalog::CHECKS
            .iter()
            .map(|c| (c.id.to_string(), CheckStats::default()))
            .collect();
        for r in &self.results {
            for e in &r.matched {
                stats.entry(e.check.clone()).or_default().tp += 1;
            }
            for e in &r.missed {
                stats.entry(e.check.clone()).or_default().fn_ += 1;
            }
            for f in &r.false_positives {
                stats.entry(f.check.clone()).or_default().fp += 1;
            }
        }
        stats
    }

    pub fn count(&self, kind: Kind) -> usize {
        self.results.iter().filter(|r| r.kind == kind).count()
    }

    /// Findings reported on fixtures that should have none.
    pub fn false_alarms_on_clean(&self) -> usize {
        self.results
            .iter()
            .filter(|r| r.expected.is_empty())
            .map(|r| r.false_positives.len())
            .sum()
    }

    /// Real labelled sessions: (count, false alarms, hallucinating sessions,
    /// of those with a statically checkable defect, of those caught).
    pub fn real_summary(&self) -> (usize, usize, usize, usize, usize) {
        let real: Vec<&FixtureResult> = self.results.iter().filter(|r| r.kind == Kind::RealLabelled).collect();
        let fps = real.iter().map(|r| r.false_positives.len()).sum();
        let hall: Vec<&&FixtureResult> = real.iter().filter(|r| r.hallucinated == Some(true)).collect();
        let checkable: Vec<&&&FixtureResult> = hall.iter().filter(|r| !r.expected.is_empty()).collect();
        let caught = checkable.iter().filter(|r| !r.matched.is_empty()).count();
        (real.len(), fps, hall.len(), checkable.len(), caught)
    }

    pub fn deterministic(&self) -> (usize, usize) {
        let ok = self.results.iter().filter(|r| r.deterministic).count();
        (ok, self.results.len())
    }

    pub fn errors(&self) -> Vec<&FixtureResult> {
        self.results.iter().filter(|r| r.error.is_some()).collect()
    }

    pub fn timing(&self) -> (f64, f64) {
        let times: Vec<f64> = self.results.iter().map(|r| r.millis).collect();
        if times.is_empty() {
            return (0.0, 0.0);
        }
        let mean = times.iter().sum::<f64>() / times.len() as f64;
        let max = times.iter().cloned().fold(0.0, f64::max);
        (mean, max)
    }

    pub fn to_json(&self) -> Value {
        let (det_ok, det_total) = self.deterministic();
        let (mean, max) = self.timing();
        let checks: Vec<Value> = self
            .checks()
            .iter()
            .map(|(id, s)| {
                json!({
                    "check": id,
                    "phase": checks::catalog::CHECKS.iter().find(|c| c.id == id).map(|c| c.phase),
                    "tp": s.tp, "fp": s.fp, "fn": s.fn_,
                    "precision": s.precision(), "recall": s.recall(),
                })
            })
            .collect();
        let results: Vec<Value> = self
            .results
            .iter()
            .map(|r| {
                json!({
                    "name": r.name,
                    "kind": r.kind.as_str(),
                    "expected": r.expected.iter().map(Expected::to_json).collect::<Vec<_>>(),
                    "found": r.found.iter().map(Finding::to_json).collect::<Vec<_>>(),
                    "missed": r.missed.iter().map(Expected::to_json).collect::<Vec<_>>(),
                    "false_positives": r.false_positives.iter().map(Finding::to_json).collect::<Vec<_>>(),
                    "deterministic": r.deterministic,
                    "millis": (r.millis * 100.0).round() / 100.0,
                    "error": r.error,
                })
            })
            .collect();
        let (n, fps, hall, checkable, caught) = self.real_summary();
        let real_sessions = json!({ "labelled": n, "false_alarms": fps, "hallucinated": hall, "statically_checkable": checkable, "caught": caught });
        json!({
            "schema": 1,
            "cv_version": capture::hook::CV_VERSION,
            "fixtures": {
                "synthetic_clean": self.count(Kind::SyntheticClean),
                "real_labelled": self.count(Kind::RealLabelled),
                "mutations": self.count(Kind::Mutation),
                "skipped": self.skipped.iter().map(|(n, why)| json!({"name": n, "reason": why})).collect::<Vec<_>>(),
                "not_applicable": self.not_applicable.iter().map(|(s, m)| json!({"source": s, "mutation": m})).collect::<Vec<_>>(),
            },
            "checks": checks,
            "false_alarms_on_clean": self.false_alarms_on_clean(),
            "real_sessions": real_sessions,
            "determinism": { "identical": det_ok, "total": det_total },
            "checker_millis": { "mean": (mean * 100.0).round() / 100.0, "max": (max * 100.0).round() / 100.0 },
            "errors": self.errors().len(),
            "results": results,
        })
    }

    pub fn to_text(&self) -> String {
        let mut s = String::new();
        let fmt = |v: Option<f64>| v.map_or("n/a".to_string(), |x| format!("{x:.2}"));
        s.push_str(&format!(
            "Fixtures: {} synthetic clean, {} real labelled, {} mutations ({} not applicable), {} real recordings skipped\n\n",
            self.count(Kind::SyntheticClean),
            self.count(Kind::RealLabelled),
            self.count(Kind::Mutation),
            self.not_applicable.len(),
            self.skipped.len(),
        ));
        s.push_str(&format!(
            "{:<30} {:>5} {:>4} {:>4} {:>4} {:>9} {:>7}\n",
            "check", "phase", "TP", "FP", "FN", "precision", "recall"
        ));
        for (id, st) in self.checks() {
            let phase = checks::catalog::CHECKS.iter().find(|c| c.id == id).map_or("?", |c| c.phase);
            s.push_str(&format!(
                "{:<30} {:>5} {:>4} {:>4} {:>4} {:>9} {:>7}\n",
                id, phase, st.tp, st.fp, st.fn_, fmt(st.precision()), fmt(st.recall())
            ));
        }
        let (det_ok, det_total) = self.deterministic();
        let (mean, max) = self.timing();
        s.push_str(&format!("\nFalse alarms on clean fixtures: {}\n", self.false_alarms_on_clean()));
        let (n, fps, hall, checkable, caught) = self.real_summary();
        if n > 0 {
            s.push_str(&format!(
                "Real sessions: {n} labelled, {fps} false alarms; {hall} with hallucinations, {checkable} of them statically checkable, {caught} caught\n"
            ));
            for r in self.results.iter().filter(|r| r.kind == Kind::RealLabelled && (!r.missed.is_empty() || !r.false_positives.is_empty())) {
                let missed: Vec<&str> = r.missed.iter().map(|e| e.check.as_str()).collect();
                let fps: Vec<&str> = r.false_positives.iter().map(|f| f.check.as_str()).collect();
                s.push_str(&format!("  {}: missed {:?}, false alarms {:?}\n", r.name, missed, fps));
            }
        }
        s.push_str(&format!("Deterministic: {det_ok}/{det_total}\n"));
        s.push_str(&format!("Checker time per fixture: mean {mean:.2} ms, max {max:.2} ms\n"));
        let errors = self.errors();
        if !errors.is_empty() {
            s.push_str(&format!("\nERRORS ({}):\n", errors.len()));
            for r in errors {
                s.push_str(&format!("  {}: {}\n", r.name, r.error.as_deref().unwrap_or("")));
            }
        }
        s
    }
}

/// Run `checker` over every fixture.
pub fn score(collected: Collected, checker: &dyn Fn(&Recording) -> Report) -> ScoreReport {
    let mut results = Vec::new();
    for f in &collected.fixtures {
        let outcome = (|| -> Result<(Report, bool, f64)> {
            let rec = Recording::load(&f.dir).with_context(|| format!("loading {}", f.dir.display()))?;
            let start = Instant::now();
            let first = checker(&rec);
            let millis = start.elapsed().as_secs_f64() * 1000.0;
            let second = checker(&rec);
            Ok((first.clone(), first.canonical_json() == second.canonical_json(), millis))
        })();
        let (report, deterministic, millis, error) = match outcome {
            Ok((r, d, m)) => (r, d, m, None),
            Err(e) => (Report::default(), false, 0.0, Some(format!("{e:#}"))),
        };
        let mut found = report.findings;
        found.sort();
        let counted: Vec<Finding> = found
            .iter()
            .filter(|x| !f.tolerated.iter().any(|t| t.check == x.check && (t.file.is_none() || t.file == x.file)))
            .cloned()
            .collect();
        let (matched, missed, false_positives) = match_findings(&f.expected, &counted);
        results.push(FixtureResult {
            hallucinated: f.hallucinated,
            name: f.name.clone(),
            kind: f.kind,
            expected: f.expected.clone(),
            found,
            matched,
            missed,
            false_positives,
            deterministic,
            millis,
            error,
        });
    }
    ScoreReport { results, skipped: collected.skipped, not_applicable: collected.not_applicable }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn finding(check: &str, file: Option<&str>) -> Finding {
        Finding { check: check.into(), file: file.map(str::to_string), seq: None, message: String::new() }
    }

    #[test]
    fn matching_counts_hits_misses_and_extras() {
        let expected = vec![Expected::new("tests.removed", Some("a.test.ts")), Expected::new("deps.added", None)];
        let found = vec![
            finding("tests.removed", Some("b.test.ts")), // wrong file
            finding("tests.removed", Some("a.test.ts")),
            finding("code.stub", Some("x.ts")),
        ];
        let (matched, missed, fps) = match_findings(&expected, &found);
        assert_eq!(matched, vec![Expected::new("tests.removed", Some("a.test.ts"))]);
        assert_eq!(missed, vec![Expected::new("deps.added", None)]);
        assert_eq!(fps.len(), 2);
    }

    #[test]
    fn expectation_without_file_matches_any_file() {
        let (m, _, fps) = match_findings(&[Expected::new("deps.added", None)], &[finding("deps.added", Some("package.json"))]);
        assert_eq!(m.len(), 1);
        assert!(fps.is_empty());
    }

    #[test]
    fn precision_and_recall() {
        let s = CheckStats { tp: 3, fp: 1, fn_: 1 };
        assert_eq!(s.precision(), Some(0.75));
        assert_eq!(s.recall(), Some(0.75));
        assert_eq!(CheckStats::default().precision(), None);
    }

    #[test]
    fn labels_need_a_labeller() {
        assert_eq!(expected_from_labels(&json!({"labeller": "", "defects": []})), None);
        let e = expected_from_labels(&json!({
            "labeller": "L",
            "defects": [{"type": "test-edited-to-pass", "file": "a.test.ts"}, {"type": "delete-test", "file": ""}]
        }))
        .unwrap();
        assert_eq!(
            e,
            vec![Expected::new("test-edited-to-pass", Some("a.test.ts")), Expected::new("tests.removed", None)]
        );
    }
}
